await check('ordinary storage-only scheduled recovery replays retained terminal facts after a committed lost usage ACK even with creation gates off',async()=>{const f=await fixture({capacity:smallCapacity}),call=await read(f),key=call.paidLegs.parent.receipt.key,set=Map.prototype.set;let lose=true;Map.prototype.set=function(k,v){const value=set.call(this,k,v);if(lose&&k===key&&typeof v?.value==='string'&&v.value.includes('actualQuantity')){lose=false;throw Error('Synthetic committed usage settlement lost ACK');}return value;};try{await signed(f,'status',{CallStatus:'completed',CallDuration:'61'});}finally{Map.prototype.set=set;}assert.equal((await read(f)).paidLegs.parent.settledProof,undefined);assert.equal((await capacityStatus(f)).units.voiceMinutes.used,2);await store.put('voice_activation_queue','active_v1',{version:1,intents:{},cursor:''});process.env.VOICE_ACTIVATION_ENABLED='false';const before=report.providerProtocol.length,scheduler=(await import('../netlify/functions/voice-activation-scheduler.mjs')).default;for(let i=0;i<25&&!(await read(f)).paidLegs.parent.settledProof;i++)assert.equal((await scheduler()).status,200);assert.equal((await read(f)).paidLegs.parent.settledProof,(await read(f)).paidLegs.parent.terminalFacts.proofId);assert.equal((await capacityStatus(f)).units.voiceMinutes.used,2);assert.equal(report.providerProtocol.length,before);});
await check('owner pause at exact pre-limit provider read prevents the TimeLimit POST and AI while strict explicit zero remains separate terminal proof',async()=>{const before=limitCount(),f=await fixture({capacity:smallCapacity,pauseBeforeLimit:true,expectUnavailable:true});assert.equal(limitCount(),before);assert.equal((await read(f)).paidLimit.status,'unknown');assert.equal((await capacityStatus(f)).units.voiceMinutes.held,2);await signed(f,'status',{CallStatus:'completed',CallDuration:'0'});assert.equal((await capacityStatus(f)).units.voiceMinutes.held,0);assert.equal((await capacityStatus(f)).units.voiceMinutes.used,0);assert.equal((await store.get('clients',f.c.slug)).status,'paused');});
await check('an unknown child whole-limit response never speaks or retries and its positive terminal duration remains chargeable',async()=>{const f=await fixture({capacity:smallCapacity});await tool(f);await signed(f,'handoff');physicalChild(f);fault='limit-after';const before=report.providerProtocol.length;assert.doesNotMatch(await(await signed(f,'handoff-screen',childParams(f))).text(),/<Gather|<Say/);assert.equal((await read(f)).paidLegs.handoff0.limit.status,'unknown');fault=null;assert.doesNotMatch(await(await signed(f,'handoff-screen',childParams(f))).text(),/<Gather|<Say/);assert.equal(report.providerProtocol.slice(before).filter(v=>v.kind==='time_limit'&&v.sid===f.child).length,1);await signed(f,'handoff-status',statusParams(f,'completed',0,{DialCallDuration:'8',DialBridged:'false'}));assert.equal((await capacityStatus(f)).units.voiceMinutes.used,1);assert.equal((await capacityStatus(f)).units.voiceMinutes.held,2);});
