await check('a terminal paid parent with missing duration retains its hold but cannot redirect or request a fresh assistant on a duplicate callback',async()=>{const f=await fixture({capacity:smallCapacity}),before=limitCount(f);await signed(f,'status',{CallStatus:'completed'});assert.equal((await capacityStatus(f)).units.voiceMinutes.held,2);assert.match(await(await signed(f,'inbound')).text(),/<Hangup\/>/);assert.equal(!!(await(await event(f,'assistant-request')).json()).assistant,false);assert.equal(limitCount(f),before);await signed(f,'status',{CallStatus:'completed',CallDuration:'61'});assert.equal((await capacityStatus(f)).units.voiceMinutes.used,2);});
