await check('first parent uses its remaining whole funded minutes and replay never enlarges its immutable bound after other calls settle',async()=>{const f=await fixture({capacity:{voiceMinutes:12,smsSegments:4,aiAnswers:2},maxSeconds:480});assert.equal((await read(f)).paidLimit.seconds,480);assert.equal((await capacityStatus(f)).units.voiceMinutes.remaining,4);const next='CA'+hash(f.parent+'remaining').slice(0,32),other={...f,parent:next,vapiId:hash(f.vapiId+'remaining')};calls.set(next,{sid:next,account_sid:account,from:f.from,to:f.row.number.number,direction:'inbound',status:'in-progress'});assert.match(await(await signed(other,'inbound')).text(),/<Redirect/);assert.ok((await(await event(other,'assistant-request')).json()).assistant);const leg=(await read(other)).paidLegs.parent,receipt=JSON.stringify(leg.receipt);assert.equal(leg.seconds,240);assert.equal(leg.receipt.quantity,4);assert.equal((await read(other)).paidLimit.seconds,240);await signed(f,'status',{CallStatus:'completed',CallDuration:'60'});assert.equal((await capacityStatus(f)).units.voiceMinutes.remaining,7);await signed(other,'inbound');await event(other,'assistant-request');assert.equal((await read(other)).paidLimit.seconds,240);assert.equal(JSON.stringify((await read(other)).paidLegs.parent.receipt),receipt);assert.equal(limitCount(other),1);});
await check('two competing parents cannot both consume the same last whole funded-minute balance',async()=>{const f=await fixture({capacity:{voiceMinutes:12,smsSegments:4,aiAnswers:2},maxSeconds:480}),others=[0,1].map(i=>({...f,parent:'CA'+hash(f.parent+'compete'+i).slice(0,32),vapiId:hash(f.vapiId+'compete'+i)}));for(const v of others)calls.set(v.parent,{sid:v.parent,account_sid:account,from:f.from,to:f.row.number.number,direction:'inbound',status:'in-progress'});const replies=await Promise.all(others.map(async v=>(await signed(v,'inbound')).text()));assert.equal(replies.filter(v=>v.includes('<Redirect')).length,1);assert.equal(replies.filter(v=>v.includes('<Hangup/>')).length,1);assert.equal((await capacityStatus(f)).units.voiceMinutes.held,12);assert.equal((await capacityStatus(f)).units.voiceMinutes.remaining,0);assert.equal(others.reduce((n,v)=>n+limitCount(v),0),1);});
